//! A small JSON Schema checker for the command output schemas (`cutweave_describe_command` ->
//! `output_schema`, generated by schemars; see `schema/commands.json`).
//!
//! It implements the keywords those schemas use: `type` (string or array), `properties`,
//! `required`, `additionalProperties` (false or a schema), `items`, `anyOf`, `oneOf`, `allOf`,
//! `const`, `enum`, `pattern`, `minimum`, `maximum`, `minLength`, `minItems`. Unknown keywords
//! (`description`, `title`, `format`, ...) are annotations and are ignored. A `$ref` is an error
//! (the registry inlines its schemas): better to fail loudly than to pass vacuously.

use regex::Regex;
use serde_json::Value;

/// Checks `value` against `schema`; the error names the first violations with their JSON
/// pointer.
pub fn check(schema: &Value, value: &Value) -> Result<(), String> {
    let mut errors = Vec::new();
    walk(schema, value, "", &mut errors);
    if errors.is_empty() {
        Ok(())
    } else {
        Err(errors.join("; "))
    }
}

fn walk(schema: &Value, value: &Value, at: &str, errors: &mut Vec<String>) {
    let here = if at.is_empty() { "/" } else { at };
    let object = match schema {
        Value::Bool(true) => return,
        Value::Bool(false) => {
            errors.push(format!("{here}: no value is allowed"));
            return;
        }
        Value::Object(o) => o,
        other => {
            errors.push(format!("{here}: the schema is not an object: {other}"));
            return;
        }
    };
    if object.contains_key("$ref") {
        errors.push(format!("{here}: unresolved $ref in the schema"));
        return;
    }
    if let Some(t) = object.get("type") {
        let names: Vec<&str> = match t {
            Value::String(s) => vec![s.as_str()],
            Value::Array(a) => a.iter().filter_map(Value::as_str).collect(),
            _ => vec![],
        };
        if !names.iter().any(|n| is_type(n, value)) {
            errors.push(format!("{here}: expected {names:?}, got {}", kind(value)));
            return;
        }
    }
    if let Some(c) = object.get("const")
        && c != value
    {
        errors.push(format!("{here}: expected the constant {c}, got {value}"));
    }
    if let Some(Value::Array(options)) = object.get("enum")
        && !options.contains(value)
    {
        errors.push(format!("{here}: {value} is not one of {options:?}"));
    }
    if let Some(Value::Array(branches)) = object.get("allOf") {
        for branch in branches {
            walk(branch, value, at, errors);
        }
    }
    if let Some(Value::Array(branches)) = object.get("anyOf") {
        let ok = branches.iter().any(|b| passes(b, value));
        if !ok {
            errors.push(format!("{here}: {} matches none of the anyOf branches", brief(value)));
        }
    }
    if let Some(Value::Array(branches)) = object.get("oneOf") {
        let n = branches.iter().filter(|b| passes(b, value)).count();
        if n != 1 {
            errors.push(format!(
                "{here}: {} matches {n} of the oneOf branches, not exactly one",
                brief(value)
            ));
        }
    }
    match value {
        Value::Object(map) => {
            if let Some(Value::Array(required)) = object.get("required") {
                for key in required.iter().filter_map(Value::as_str) {
                    if !map.contains_key(key) {
                        errors.push(format!("{here}: missing required property `{key}`"));
                    }
                }
            }
            let properties = object.get("properties").and_then(Value::as_object);
            for (key, member) in map {
                let child = format!("{at}/{}", key.replace('~', "~0").replace('/', "~1"));
                match properties.and_then(|p| p.get(key)) {
                    Some(schema) => walk(schema, member, &child, errors),
                    None => match object.get("additionalProperties") {
                        Some(Value::Bool(false)) => {
                            errors.push(format!("{child}: unexpected property"));
                        }
                        Some(extra @ Value::Object(_)) => walk(extra, member, &child, errors),
                        _ => {}
                    },
                }
            }
        }
        Value::Array(items) => {
            if let Some(Value::Number(min)) = object.get("minItems")
                && min.as_u64().is_some_and(|m| (items.len() as u64) < m)
            {
                errors.push(format!("{here}: fewer than {min} items"));
            }
            if let Some(schema) = object.get("items") {
                for (i, item) in items.iter().enumerate() {
                    walk(schema, item, &format!("{at}/{i}"), errors);
                }
            }
        }
        Value::String(s) => {
            if let Some(Value::String(pattern)) = object.get("pattern") {
                match Regex::new(pattern) {
                    Ok(re) if !re.is_match(s) => {
                        errors.push(format!("{here}: {s:?} does not match /{pattern}/"));
                    }
                    Ok(_) => {}
                    Err(e) => errors.push(format!("{here}: bad pattern /{pattern}/: {e}")),
                }
            }
            if let Some(Value::Number(min)) = object.get("minLength")
                && min.as_u64().is_some_and(|m| (s.chars().count() as u64) < m)
            {
                errors.push(format!("{here}: shorter than {min} characters"));
            }
        }
        Value::Number(n) => {
            let x = n.as_f64().unwrap_or(f64::NAN);
            if let Some(min) = object.get("minimum").and_then(Value::as_f64)
                && x < min
            {
                errors.push(format!("{here}: {n} is below the minimum {min}"));
            }
            if let Some(max) = object.get("maximum").and_then(Value::as_f64)
                && x > max
            {
                errors.push(format!("{here}: {n} is above the maximum {max}"));
            }
        }
        _ => {}
    }
}

fn passes(schema: &Value, value: &Value) -> bool {
    let mut errors = Vec::new();
    walk(schema, value, "", &mut errors);
    errors.is_empty()
}

fn is_type(name: &str, value: &Value) -> bool {
    match name {
        "object" => value.is_object(),
        "array" => value.is_array(),
        "string" => value.is_string(),
        "boolean" => value.is_boolean(),
        "null" => value.is_null(),
        "number" => value.is_number(),
        "integer" => {
            value.is_i64()
                || value.is_u64()
                || value
                    .as_f64()
                    .is_some_and(|f| f.fract() == 0.0 && f.is_finite())
        }
        _ => false,
    }
}

fn kind(value: &Value) -> &'static str {
    match value {
        Value::Null => "null",
        Value::Bool(_) => "boolean",
        Value::Number(_) => "number",
        Value::String(_) => "string",
        Value::Array(_) => "array",
        Value::Object(_) => "object",
    }
}

fn brief(value: &Value) -> String {
    let text = value.to_string();
    if text.len() > 80 {
        format!("{}...", &text[..text.char_indices().nth(80).map_or(text.len(), |(i, _)| i)])
    } else {
        text
    }
}
